{"tool":"write","path":"tests/test_export_csv.py","content":""""Focused tests for reports.export.export_csv."""
import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_empty_rows_with_columns(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_both(self):
        self.assertEqual(export_csv([], []), "\r\n")

    def test_none_and_missing(self):
        self.assertEqual(export_csv([{"a": None, "b": "x"}], ["a", "b", "c"]),
                         "a,b,c\r\n,x,\r\n")

    def test_numbers_and_other_values(self):
        self.assertEqual(export_csv([{"a": 1, "b": 2.5, "c": True}], ["a", "b", "c"]),
                         "a,b,c\r\n1,2.5,True\r\n")

    def test_embedded_newlines_and_quotes(self):
        rows = [{"a": "line1\nline2\r\nline3", "b": 'say "hi"'}]
        self.assertEqual(export_csv(rows, ["a", "b"]),
                         'a,b\r\n"line1\nline2\r\nline3","say ""hi"""\r\n')

    def test_unicode_preserved(self):
        self.assertEqual(export_csv([{"a": "caf\u00e9 \u4e2d\u6587"}], ["a"]),
                         "a\r\ncaf\u00e9 \u4e2d\u6587\r\n")

    def test_ignore_unselected_fields(self):
        self.assertEqual(export_csv([{"a": 1, "extra": "zzz"}], ["a"]),
                         "a\r\n1\r\n")

    def test_rows_generator_one_shot(self):
        gen = ({"a": i, "b": i * 2} for i in range(3))
        self.assertEqual(export_csv(gen, ["a", "b"]),
                         "a,b\r\n0,0\r\n1,2\r\n2,4\r\n")

    def test_columns_generator_one_shot(self):
        cols = (name for name in ["a", "b"])
        self.assertEqual(export_csv([{"a": 1, "b": 2}], cols),
                         "a,b\r\n1,2\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"a": 1}], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{1: "x"}], [1])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1, "b": 2}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()
